import { useEffect, useRef } from "react";
import * as THREE from "three";
import { GLTFLoader } from "three/examples/jsm/loaders/GLTFLoader.js";
import { RoomEnvironment } from "three/examples/jsm/environments/RoomEnvironment.js";
import type { Goal } from "@/types/database/Goal";

// "Mechanical Wheel": generated by cad/mechanical_wheel.py (nodes rim_0..rim_3 + static parts).
const MODEL_URL = `${import.meta.env.BASE_URL}models/mechanical_wheel.glb`;
const MODEL_RADIUS_MM = 77.5; // gear tip radius
const VIEW_RADIUS = 1.5;

interface Props {
  goals: Goal[];
  onHoverChange: (hovering: boolean, mouseX: number, mouseY: number) => void;
}

export function getWeeklyRingSegments(
  goals: Pick<Goal, "title" | "completed">[]
) {
  return goals.length > 0
    ? goals
    : Array.from({ length: 4 }, () => ({ title: "", completed: false }));
}

export function WeeklyTorusRing({ goals, onHoverChange }: Props) {
  const mountRef = useRef<HTMLDivElement>(null);
  const onHoverChangeRef = useRef(onHoverChange);
  const goalsRef = useRef(goals);

  useEffect(() => {
    onHoverChangeRef.current = onHoverChange;
  }, [onHoverChange]);
  useEffect(() => {
    goalsRef.current = goals;
  }, [goals]);

  // Recompute stable key so the scene only rebuilds when content changes
  const goalsKey = goals
    .map((g) => `${g.id}:${g.completed}:${g.title}`)
    .join("|");

  useEffect(() => {
    const el = mountRef.current;
    if (!el) return;

    // ponytail: the wheel has 4 fixed quadrants; rim_i shows segments[i], extra goals aren't drawn
    const currentGoals = getWeeklyRingSegments(goalsRef.current);

    const scene = new THREE.Scene();
    const camera = new THREE.PerspectiveCamera(45, 1, 0.1, 100);
    camera.position.z = 4.0;

    const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true });
    renderer.setClearColor(0x000000, 0);
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    renderer.toneMapping = THREE.ACESFilmicToneMapping;
    const canvas = renderer.domElement;
    canvas.style.cssText = "display:block;width:100%;height:100%;";
    el.appendChild(canvas);

    const pmrem = new THREE.PMREMGenerator(renderer);
    const envTex = pmrem.fromScene(new RoomEnvironment(), 0.04).texture;
    scene.environment = envTex;
    const key = new THREE.DirectionalLight(0xfff1e6, 1.4);
    key.position.set(2, 3, 4);
    scene.add(key);

    const resize = () => {
      const W = el.offsetWidth,
        H = el.offsetHeight;
      if (W > 0 && H > 0) {
        renderer.setSize(W, H, false);
        camera.aspect = W / H;
        camera.updateProjectionMatrix();
      }
    };
    resize();

    const matDone = new THREE.MeshStandardMaterial({
      color: 0xf06020,
      metalness: 0.35,
      roughness: 0.4,
    });
    const matTodo = new THREE.MeshStandardMaterial({
      color: 0xc4a898,
      metalness: 0.55,
      roughness: 0.5,
    });
    const matSteel = new THREE.MeshStandardMaterial({
      color: 0xb3aaa3,
      metalness: 0.75,
      roughness: 0.35,
    });
    const matDark = new THREE.MeshStandardMaterial({
      color: 0x7d746e,
      metalness: 0.85,
      roughness: 0.3,
    });

    const group = new THREE.Group();
    group.rotation.x = (20 * Math.PI) / 180;
    scene.add(group);

    const hitMeshes: THREE.Mesh[] = [];
    const geos: THREE.BufferGeometry[] = [];
    let wheel: THREE.Object3D | null = null;
    let disposed = false;

    new GLTFLoader().load(MODEL_URL, (gltf) => {
      if (disposed) return;
      wheel = gltf.scene;
      wheel.scale.setScalar(VIEW_RADIUS / MODEL_RADIUS_MM);
      wheel.traverse((obj) => {
        if (!(obj instanceof THREE.Mesh)) return;
        (obj.material as THREE.Material).dispose();
        geos.push(obj.geometry);
        const rim = /^rim_(\d)/.exec(obj.name);
        if (rim) {
          obj.material = currentGoals[Number(rim[1])]?.completed
            ? matDone
            : matTodo;
          hitMeshes.push(obj);
        } else {
          obj.material = /bearing|fasteners/.test(obj.name)
            ? matDark
            : matSteel;
        }
      });
      group.add(wheel);
    });

    // Raycaster
    const raycaster = new THREE.Raycaster();
    const mouseNDC = new THREE.Vector2(-999, -999);
    const mouseClient = { x: 0, y: 0 };
    let isHovering = false;

    const handleMouseMove = (e: MouseEvent) => {
      const rect = el.getBoundingClientRect();
      mouseNDC.set(
        ((e.clientX - rect.left) / rect.width) * 2 - 1,
        -((e.clientY - rect.top) / rect.height) * 2 + 1
      );
      mouseClient.x = e.clientX;
      mouseClient.y = e.clientY;
      // Continuously update popup position while hovering
      if (isHovering) {
        onHoverChangeRef.current(true, e.clientX, e.clientY);
      }
    };

    const handleMouseLeave = () => {
      mouseNDC.set(-999, -999);
      if (isHovering) {
        isHovering = false;
        onHoverChangeRef.current(false, 0, 0);
      }
    };

    el.addEventListener("mousemove", handleMouseMove);
    el.addEventListener("mouseleave", handleMouseLeave);

    let rafId: number;
    const animate = () => {
      rafId = requestAnimationFrame(animate);
      group.rotation.y += 0.001;
      if (wheel) wheel.rotation.z -= 0.0015; // slow gear turn
      renderer.render(scene, camera);

      // Raycast after render so world matrices are up to date
      raycaster.setFromCamera(mouseNDC, camera);
      const nowHovering = raycaster.intersectObjects(hitMeshes).length > 0;
      if (nowHovering !== isHovering) {
        isHovering = nowHovering;
        onHoverChangeRef.current(isHovering, mouseClient.x, mouseClient.y);
      }
    };
    animate();

    const ro = new ResizeObserver(resize);
    ro.observe(el);

    return () => {
      disposed = true;
      cancelAnimationFrame(rafId);
      ro.disconnect();
      el.removeEventListener("mousemove", handleMouseMove);
      el.removeEventListener("mouseleave", handleMouseLeave);
      geos.forEach((g) => g.dispose());
      [matDone, matTodo, matSteel, matDark].forEach((m) => m.dispose());
      envTex.dispose();
      pmrem.dispose();
      renderer.dispose();
      if (el.contains(canvas)) el.removeChild(canvas);
    };
  }, [goalsKey]); // eslint-disable-line react-hooks/exhaustive-deps

  return (
    <div
      ref={mountRef}
      role="img"
      aria-label={`Weekly goal ring with ${getWeeklyRingSegments(goals).length} segments, ${goals.filter((goal) => goal.completed).length} completed`}
      className="w-full"
      style={{ height: "320px", marginTop: "20px", marginBottom: "8px" }}
    />
  );
}
